{
  "name": "SR830 锁相放大器",
  "name_en": "SR830 Lock-in Amplifier",
  "manufacturer": "Stanford Research Systems",
  "description": "SR830 是一款用于相敏检测和微弱交流信号测量的锁相放大器。该驱动通过 GPIB/串口控制参考源、频率、谐波、输入耦合、灵敏度、时间常数、滤波器、显示/前面板输出、模拟输入输出以及内部数据缓冲与存储功能。",
  "description_en": "The SR830 is a lock-in amplifier for phase-sensitive detection and measurement of weak AC signals. This driver controls the instrument over GPIB/serial, including reference source, frequency, harmonic, input coupling, sensitivity, time constant, filters, display/front-panel outputs, analog I/O, and the internal data buffer and storage functions.",
  "tag_hints": [
    "lock-in amplification",
    "phase-sensitive detection",
    "weak AC signal measurement",
    "reference oscillator control",
    "time constant and filter settings",
    "data buffer acquisition",
    "GPIB instrument control"
  ],
  "actions": [
    {
      "action_name": "auto-auto_gain_async_async",
      "description": "异步执行自动增益调整。",
      "description_en": "Run auto gain adjustment asynchronously."
    },
    {
      "action_name": "auto-auto_offset_async_async",
      "description": "异步执行自动偏移调整。",
      "description_en": "Run auto offset adjustment asynchronously."
    },
    {
      "action_name": "auto-auto_phase_async_async",
      "description": "异步执行自动相位调整。",
      "description_en": "Run auto phase adjustment asynchronously."
    },
    {
      "action_name": "auto-auto_reserve_async_async",
      "description": "异步执行自动储备模式调整。",
      "description_en": "Run auto reserve adjustment asynchronously."
    },
    {
      "action_name": "auto-measure_async",
      "description": "异步执行测量并返回锁相读数。",
      "description_en": "Perform a measurement asynchronously and return lock-in readings."
    },
    {
      "action_name": "auto-pause_data_storage_async",
      "description": "异步暂停内部数据存储。",
      "description_en": "Pause internal data storage asynchronously."
    },
    {
      "action_name": "auto-read_buffer_async",
      "description": "异步读取内部数据缓冲区。",
      "description_en": "Read the internal data buffer asynchronously."
    },
    {
      "action_name": "auto-recall_state_async",
      "description": "异步调用已保存的仪器状态。",
      "description_en": "Recall a saved instrument state asynchronously."
    },
    {
      "action_name": "auto-reset_data_storage_async",
      "description": "异步重置内部数据存储。",
      "description_en": "Reset internal data storage asynchronously."
    },
    {
      "action_name": "auto-save_state_async",
      "description": "异步保存当前仪器状态。",
      "description_en": "Save the current instrument state asynchronously."
    },
    {
      "action_name": "auto-start_data_storage_async",
      "description": "异步启动内部数据存储。",
      "description_en": "Start internal data storage asynchronously."
    },
    {
      "action_name": "auto-trigger_async",
      "description": "异步发送触发命令。",
      "description_en": "Send a trigger command asynchronously."
    },
    {
      "action_name": "auto-reference_phase_shift",
      "description": "获取/设置参考相位偏移。",
      "description_en": "Get/set the reference phase shift."
    },
    {
      "action_name": "auto-reference_internal",
      "description": "获取/设置是否使用内部参考源。",
      "description_en": "Get/set whether the internal reference source is used."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置参考频率。",
      "description_en": "Get/set the reference frequency."
    },
    {
      "action_name": "auto-reference_trigger",
      "description": "获取/设置参考触发方式。",
      "description_en": "Get/set the reference trigger mode."
    },
    {
      "action_name": "auto-harmonic",
      "description": "获取/设置检测谐波。",
      "description_en": "Get/set the detection harmonic."
    },
    {
      "action_name": "auto-sine_output_amplitude",
      "description": "获取/设置正弦输出幅度。",
      "description_en": "Get/set the sine output amplitude."
    },
    {
      "action_name": "auto-input_configuration",
      "description": "获取/设置输入配置。",
      "description_en": "Get/set the input configuration."
    },
    {
      "action_name": "auto-input_shield",
      "description": "获取/设置输入屏蔽方式。",
      "description_en": "Get/set the input shield mode."
    },
    {
      "action_name": "auto-input_coupling",
      "description": "获取/设置输入耦合方式。",
      "description_en": "Get/set the input coupling."
    },
    {
      "action_name": "auto-input_filter",
      "description": "获取/设置输入滤波方式。",
      "description_en": "Get/set the input filter."
    },
    {
      "action_name": "auto-sensitivity",
      "description": "获取/设置灵敏度量程。",
      "description_en": "Get/set the sensitivity range."
    },
    {
      "action_name": "auto-reserve_mode",
      "description": "获取/设置储备模式。",
      "description_en": "Get/set the reserve mode."
    },
    {
      "action_name": "auto-time_constants",
      "description": "获取/设置时间常数。",
      "description_en": "Get/set the time constant."
    },
    {
      "action_name": "auto-filter_db_per_oct",
      "description": "获取/设置低通滤波器滚降斜率。",
      "description_en": "Get/set the low-pass filter roll-off."
    },
    {
      "action_name": "auto-sync_filter",
      "description": "获取/设置同步滤波器状态。",
      "description_en": "Get/set the sync filter state."
    },
    {
      "action_name": "auto-display",
      "description": "获取/设置显示通道内容。",
      "description_en": "Get/set the display channel content."
    },
    {
      "action_name": "auto-front_output",
      "description": "获取/设置前面板输出内容。",
      "description_en": "Get/set the front-panel output assignment."
    },
    {
      "action_name": "auto-analog_input",
      "description": "读取模拟输入通道值。",
      "description_en": "Read an analog input channel value."
    },
    {
      "action_name": "auto-analog_output",
      "description": "获取/设置模拟输出通道值。",
      "description_en": "Get/set an analog output channel value."
    },
    {
      "action_name": "auto-remote",
      "description": "获取/设置远程控制状态。",
      "description_en": "Get/set the remote control state."
    },
    {
      "action_name": "auto-key_click_enabled",
      "description": "获取/设置按键提示音状态。",
