    },
    {
      "action_name": "auto-recall_state",
      "description": "调用已保存的仪器状态。",
      "description_en": "Recall a saved instrument state."
    },
    {
      "action_name": "auto-save_state",
      "description": "保存当前仪器状态。",
      "description_en": "Save the current instrument state."
    },
    {
      "action_name": "auto-wait_bit1",
      "description": "等待状态位 1 置位。",
